WITH exploded AS (SELECT id, created_at, code FROM carts LATERAL VIEW EXPLODE(coupon_codes) t AS code) SELECT DATE_TRUNC('DAY', created_at) AS activity_day, code, COUNT(DISTINCT id) AS distinct_ids, MAX(created_at) AS ended_at, COUNT(*) AS row_count, GROUPING(DATE_TRUNC('DAY', created_at)) AS grouping_level FROM exploded GROUP BY ROLLUP (DATE_TRUNC('DAY', created_at), code) ORDER BY row_count ASC;
